use std::{fs, io};
fn main() -> io::Result<()> {
    // Crabrix guest path; choose a local path for desktop Cargo.
    fs::write("/sandbox/report.txt", "crab: 3\n")?;
    let text =
        fs::read_to_string("/sandbox/report.txt")?;
    assert_eq!(text, "crab: 3\n");
    Ok(())
}

